export function statsView(ctx){
 const {repo,services}=ctx,auth=authorization(ctx),rawRepo=raw(ctx);if(!auth.hasPermission('stats.view'))return denied();const all=services.stats.list(),eventId=new URLSearchParams(location.search).get('event')||all.find(x=>x.entries>0)?.eventId||all[0]?.eventId,st=all.find(x=>x.eventId===eventId),e=repo.get('events',eventId);if(!st)return empty('Aucune statistique','Les stats apparaîtront après collecte.');const max=Math.max(1,...st.hourly.map(x=>x[1])),canPublish=auth.hasPermission('events.publish'),canFinance=auth.canReadAccounting(rawRepo.state.currentUserId,rawRepo.state.activeStructureId),financeCards=canFinance?`${card('Revenus',money(st.revenue),'privé — event sélectionné','#','euro')}${card('Résultat réel',st.actualProfit==null?'—':money(st.actualProfit),`estimé ${money(st.estimatedProfit)}`,'#','chart')}`:`${card('Données financières','Restreintes','permission comptabilité requise','#','lock')}`;
 return pageHead({iconName:'chart',title:'Stats soirées',sub:'Statistiques opérationnelles, séparées des données financières.',actions:`<select class="select" id="statsEvent">${all.map(x=>`<option value="${x.eventId}" ${x.eventId===eventId?'selected':''}>${h(repo.get('events',x.eventId)?.title||x.eventId)}</option>`).join('')}</select><button class="btn" data-action="export-stats" data-id="${eventId}">Export opérationnel</button>${canFinance?`<button class="btn" data-action="export-stats-finance" data-id="${eventId}">Export financier</button>`:''}${canPublish?`<button class="btn ${st.publicSummary?'':'ghost-gold'}" data-action="toggle-public-summary" data-id="${st.id}">${st.publicSummary?'Retirer le résumé public':'Créer un résumé public'}</button>`:''}`})+`<div class="card-grid kpis">${card('Entrées',st.entries,`${st.scans} scans validés`,'#','users')}${card('Capacité',`${Math.round(st.entries/st.capacity*100)||0}%`,`${st.entries} / ${st.capacity}`,'#','chart')}${financeCards}</div><div class="grid-2"><article class="panel"><div class="panel-head"><h2>Entrées par heure</h2><b>${h(e?.title||'')}</b></div><div class="bars-real">${st.hourly.length?st.hourly.map(([t,n])=>`<div class="bar-real"><i style="height:${Math.max(4,n/max*100)}%"></i><span>${h(t)}</span><b>${n}</b></div>`).join(''):empty('Pas encore de données','Cet événement n’a pas commencé.')}</div></article><article class="panel"><div class="panel-head"><h2>Points d’entrée</h2>${st.publicSummary?badge('Résumé public actif','green'):badge('Résumé public OFF','gray')}</div><div class="panel-body">${st.entryPoints.map(([name,n])=>`<div class="stat-row"><span>${h(name)}</span><b>${n}</b></div>`).join('')||'<p class="row-sub">Pas de données.</p>'}</div></article></div>`;
}


